# The SU2000 games this build runs. Sha1 = the EXE the hook table was built against
# (the circulating "VR 2000 Series Disc Image (Simon's)" HDD dump). Args = the operator
# launch line from the game's own *RUN.BAT. Fps = frame limiter for games that step per frame.
# Link = linked-pod multiplayer works (play.ps1 -Pod). AimHead = the game aims where you look (the aim trim tilts the head). NoWalk = no stick back/strafe (rail / ring games). WalkTurn = back/strafe turn the head the game sees (it walks where you look). NoTurn = no stick/grip turning (look-around only). Clip = visible bottom of the 2D layer (screen rows). ScreenH = height of the game's 2D screen in rows (PEARL: 248; default 288). FlicPace = videos play at the FLIC file's speed. GlyphColour = 1 bpp letters in their own colour + black drop shadow. HandXY / HeadXY = tracker position scale (default = DAC's). Lean = sticks hold a head lean of up to this many mm (the game moves you by lean). JoyAxes = thumbsticks feed the pod joystick's x/y axes. DeskConverge = window mode: distance in mm where the gun meets the view ray (default 8000). HeadCentre = the spot you stand on (at launch and each coin/start) is the pod centre (the game reads head x/y as lean). Materials = type 0x68 polygons take their texture from the PIX_SetMaterial table (Pac-Man's frightened blue ghost). HideOwnHead = don't draw the player's own head model, which the game locks just behind the eye (DAC: the view went inside it). Crouch = the crouch button (digital: Vive left menu / Index right B, held) feeds the head 400 mm lower (VPIX_CROUCH_MM): the game's crouch state is head z < player_height - 200 (DAC/DN2; Pac-Man never reads head z). HoldView = when the game freezes its in-head camera (DAC/DN2 round over), keep that camera as the position anchor with live head look, the own gun on the controller, the own body following the head and own shots hidden (it locked rigid to the face; DAC: only at GAME OVER, game_mode 3). BlitPriority = 2D bitmaps in the card's priority order (model slot +0x54); an opaque picture at the lowest priority is the background under the 3D models and texts (DAC title/intro picture hid "PRESS ... TO START" and the 3D logos). DepthFix = reversed-Z 32-bit float depth buffer, infinite far plane (distant surfaces a few units apart z-fought: floor decals showing the layer under). PrioLayers = models drawn back to front in the card's priority layers, depth cleared per layer (Olin Shotgun: back panel + big-top dome hid the targets). ScaredFace = frightened / flashing ghosts wear the game's scared eye + mouth textures (loaded but never used by the game). FlicCentre = the game passes a video's CENTRE as its position (Pac-Man attract board), not its corner. DeathBox = the black box the game puts round a dead / respawning player (objects\box*.bin) is drawn only while the camera is inside it (your own death blackout), not as a black block round other players. Boxing only (same as run_game.sh box): ForceGlove = own forearm + glove forced into the first-person view (red). HandFwdOff = character select: fed hand shifted back this many mm (also turns on ring detection for HandReachFight / HandXSpread / MenuFwdFlip). MenuFwdFlip = character select: forward axis mirrored (menu punch fires on a forward jab). HandReachFight = reach multiplier in the ring. HandXSpread = "scale,mm" fists spread apart in the ring. HandZRight = right glove fed this many mm lower (live trim: left touchpad up/down). KoLift / KoExtra = a KO'd boxer is lifted so his lowest vertex sits on the mat (+ margin). DecalStack / DecalBias = coplanar ring-floor decals drawn in card order with a depth bias (no flicker).
$Games = [ordered]@{
    'DAC'   = @{ Name = 'Dactyl Nightmare';   Args = '/vcc /d';             Fps = 0;  Link = $true; HideOwnHead = $true; Crouch = $true; HoldView = $true; BlitPriority = $true; DepthFix = $true; DeathBox = $true; Haptic = 'dactwep=g:50:0.8,ouch=b:160:1,femouch=b:160:1,bodhit=b:120:0.9'; Sha1 = '5151a6d58b95a74fb86cb0dbd53a36d67eef7ce7' }
    'DN2'   = @{ Name = 'Dactyl Nightmare 2'; Args = '/vcc';                Fps = 0;  FlicPace = $true; Crouch = $true; HoldView = $true; DepthFix = $true; DecalStack = $true; DecalBias = '2e-5'; Haptic = 'dactwep=g:50:0.8,ouch=b:160:1,femouch=b:160:1,bodyhit=b:120:0.9'; Sha1 = '110d8f51aa1fc9b41d197d6cb2fb35bc0e488bf2' }
    'PAC'   = @{ Name = 'Pac-Man VR';         Args = '/vcc /solo';          Fps = 0;  WalkTurn = $true; Materials = $true; FlicCentre = $true; ScaredFace = $true; BlitUnder = 'bells'; DepthFix = $true; Haptic = 'death.wav=b:400:1'; Sha1 = '8122b1e2c672363f6b0798d8af0a4b57e715199b'
                 Cd = 'PACMAN.CUE'; CdBin = 'PACMAN.BIN'; CdSha1 = 'f3be2645f89b8e06441d46346402d2625b78906d' }
    'MISS'  = @{ Name = 'Missile Command VR'; Args = '/1 /vcc /n';          Fps = 0;  AimHead = $true; FollowPitch = $true; StickTwist = 45; ScreenH = 248; WorldScale = '0.6'; BlitNudge = '1,2'; OnTop = 'skip.bin'; NoWalk = $true; NoTurn = $true; JoyAxes = $true; Haptic = 'laser04=g:40:0.6'; Sha1 = '457781d87ed9a5294bf1d615d08fffbaac5c8b38' }
    'GUN'   = @{ Name = 'Olin Shotgun';       Args = '/vcc';                Fps = 30; NoWalk = $true; PrioLayers = $true; Haptic = 'shot=g:70:1'; Sha1 = '35ec8e0c619b2c6039773ca364ed4c350cb2c7dd' }
    'BOX'   = @{ Name = 'Virtuality Boxing';  Args = '/vcc';                Fps = 30; NoTurn = $true; DepthFix = $true; HandXY = '1'; HandZ = '0.5,300'; HeadXY = 1; Lean = 300; HeadCentre = $true; TwoHands = $true
                 ForceGlove = $true; GloveTrack = $true; HandFwdOff = 400; MenuFwdFlip = $false; HandReachFight = '1.1'; HandXSpread = '1.2,80'; HandZRight = 40
                 KoLift = $true; KoExtra = 5; DecalStack = $true; DecalBias = '2e-5'; Haptic = 'punch=b:60:0.9,hurtbit=b:160:1'; Sha1 = '3cab0abe8db32fe93a65036f71e50fae1e8e8be8' }
    'ZONE'  = @{ Name = 'Zone Hunter';        Args = '/e /c /T /D3 /1 /vcc'; Fps = 0; DepthFix = $true; PictureBack = $true; FollowLatch = $true; OneSided = 'vr_logo,room0.bin*,room3.bin*,room4.bin*,kickw\chest.bin#,kickw\abdomen.bin#,kickw\hip.bin#'; PolySelect = 'scorepow,room3.bin,room4.bin,powerpil'; ClampY = 'room3.bin:-9600@room5,room4.bin:-9600@room5,doorl.bin:-100:100,doorr.bin:-100:100,gendoorl:-100:100,gendoorr:-100:100,chuckl:-100:100,chuckr:-100:100'; MoveY = 'powerpil:-327:-392'; NearModels = 'doorl,doorr,room0.bin,room2.bin,room3.bin,room4.bin,room49.bin,checkp,room18.bin,room52.bin'; ArmToGun = $true; TimerCopy = $true; DecalStack = $true; DecalBias = '2e-5'; Haptic = 'pulse1=g:50:0.8,hit2stat=b:160:1'; Sha1 = '789182743b8c3eb924cfc71651301b3a0331d45d' }
    'GHOST' = @{ Name = 'Ghost Train';        Args = '/c1 /vcc';            Fps = 0;  NoWalk = $true; NoTurn = $true; Clip = 268; GlyphColour = $true; JoyAxes = $true; TopButtons = $true; DeskConverge = 4000; Haptic = 'gun0=g:50:0.8,fire.wav=g:50:0.8,ouch=b:160:1,bodhit=b:120:0.9'; Sha1 = 'ce0a36969d418cd591c0e7f32f9e3a35c6748adc' }
    'SFL'   = @{ Name = 'Shoot For Loot';     Args = '/vcc';                Fps = 60; PictureBack = 2; BlitPriority = $true; DepthFix = $true; DecalStack = $true; DecalBias = '2e-5'; NearModels = 'arrow0'; HideAbove = 5000; HandRoll = $true; Haptic = 'shot1=g:50:0.8,laser=g:40:0.6'; Sha1 = '426e1e7df0a5b591a1425840a18b0793d73e14d7' }
    'PEARL' = @{ Name = 'Sea Diving (Pearl)'; Args = '/vcc';                Fps = 0;  ScreenH = 248; Haptic = 'dactwep=g:50:0.8,ouch=b:160:1,femouch=b:160:1,bodyhit=b:120:0.9'; Sha1 = '8899b1988af04002188526acc6e3381ff133b23b' }
}
